-- Media generated by AI from a creative script. Keeps the prompt even after the media is released
-- (media_id becomes null), so prompts can later be compared with post results.
create table generations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references users (id) on delete cascade,
  script_id uuid references creative_scripts (id) on delete set null,
  kind text not null check (kind in ('image', 'video')),
  prompt text not null,
  provider_job_id text,
  status text not null default 'running' check (status in ('running', 'done', 'failed')),
  media_id uuid references media (id) on delete set null,
  failure_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index generations_user_created on generations (user_id, created_at desc);
create index generations_running on generations (created_at) where status = 'running';
create trigger generations_updated_at before update on generations
  for each row execute function set_updated_at();
